def voice_filter(key, text):
    if key == "dorothy@doro":
        return doro_only(text)
    if key == "marian@modernia":
        if text in _marian_only():
            return random.choice(MODERNIA_LINES)
        return text.replace("지휘관님", "지히간").replace("지휘관", "지히간")
    return text

def persona_of(name, d):
    """그림(6번 시트)이 실제로 있는 개성 동작만 — 없는 시트는 건너뜀.
    name 이 '캐릭터@모습' 이고 그 모습 전용 개성 동작이 있으면 그걸, 없으면 캐릭터 공통"""
    if name not in PERSONA:
        name = name.split("@")[0]
    return [it for it in PERSONA.get(name, [])
            if all(os.path.exists(os.path.join(d, f"{f}.png")) for f in it[0])]


# ── 띄울 모니터 (settings.json "screen": 모니터 이름, 없으면 주 모니터) ─────────
SCREEN = {"name": None}

def target_screen():
    for sc in QApplication.screens():
        if SCREEN["name"] and sc.name() == SCREEN["name"]:
            return sc
    return QApplication.primaryScreen()       # 저장한 모니터가 빠져 있으면 주 모니터로

CHAR_SCREEN = {}                              # 캐릭터별 모니터 (settings.json "char_screen")

def screen_for(char):
    want = CHAR_SCREEN.get(char)
    if want:
        for sc in QApplication.screens():
            if sc.name() == want:
                return sc
    return target_screen()


