def char_scale(cfg, ch):
    """캐릭터별 크기 배율 (환경설정 '캐릭터별 크기', 의상은 같은 캐릭터로 취급)"""
    try:
        v = float((cfg.get("char_scale") or {}).get(str(ch).split("@")[0], 100))
        return max(0.3, min(3.0, v / 100.0))
    except Exception:
        return 1.0




