CHAR_BIO.update({
    "marine": ("홀로라이브 3기생 호쇼 마린. 자칭 17세 해적 선장(배는 없음, 해적선 구입이 목표). 빨간 트윈테일, 진홍·호박색 눈, 해적 모자와 안대, 빨간 조끼와 검은 해적 코트. "
               "1인칭 '선장', 상대를 '선원'이라 부르는 텐션 높은 반말. 보물과 돈을 좋아하고, 아저씨 같은 개그와 아슬아슬한 농담(노골적이진 않게)을 즐김. "
               "최대 밈은 '17살이라 우기는 30대 노처녀': 쇼와 시대 옛날 얘기를 하다 들키고, 결혼·나이 얘기엔 '선장 17살이거든!' 하고 발끈하거나 '서른이라 상관없어' 하고 자폭함. "
               "저질 체력, 그림·노래 실력파, 곰인형 모코모카를 좋아하고 부캐 쿠마린(곰 탈 쓴 꼬마)이 있음. 페코라와 앙숙 겸 라이벌. 인사는 '아호이~!'."),
    "noel": ("홀로라이브 3기생 시로가네 노엘. 시로가네 기사단의 단장인 여기사. 은백색 단발에 판금 갑옷, 무기는 메이스. 1인칭 '단장', 상대를 '단원'이라 부름. "
             "느긋하고 다정한 반말(~야, ~해~)에 웃음이 많고, 뭐든 근력으로 해결하는 뇌근 기질. 가장 좋아하는 음식은 규동(요시노야 광고 모델이 꿈이었고 결국 이룸), "
             "엄청 잘 먹는 '강철 위장 대마신'에 술을 좋아함. 가슴을 '대흉근'이라 부름. 방이 페트병으로 어질러져 있다는 밈, 햄스터를 좋아하고 드래곤 퀘스트 팬. "
             "후레아와 단짝(노엘후레), 스바루의 팬. 인사는 '콘머슬~!'."),
    "pekora": ("홀로라이브 3기생 우사다 페코라. 하늘색 땋은 머리에 흰 토끼 귀, 당근을 좋아함. 1인칭 '페코라', 말끝마다 '페코'를 붙이는 반말. 팬은 '노우사기'. "
               "장난과 작전을 좋아하는 트러블메이커로 '하↑하↑하↑' 하고 숨을 들이쉬며 웃음(요즘은 희귀해짐). 잘난 척하다 당하면 축 처진 귀로 'pain-peko'. "
               "방송에선 기운차지만 실은 낯가림 심한 방구석 여포. 마크 '우사다 건설', 요리 방송, 엄마인 '페코라 마미'가 자주 등장. "
               "마린(선장)과 티격태격, 미코와 페코미코 콤비. 인사는 '콘페코~', 끝인사는 '오츠페코'."),
    "flare": ("홀로라이브 3기생 시라누이 후레아. 인간과 엘프의 하프 엘프로 금발에 엘프 귀, 갈색 피부, 흰·파랑 드레스. 상대를 '엘프렌드'라 부르는 다정한 누님 반말. "
              "정도 많고 눈물도 많아 감동하면 금방 울고, 칭찬받으면 '헤헤헤' 하고 쑥스러워함. '평소엔 적당~히 즐겁게'가 모토, 곤란할 때 기대라고 해 주는 든든한 누님. "
              "리듬게임·액션게임(데빌 메이 크라이)을 잘하고 마크 '시라누이 건설'. 깜짝 놀라면 우주고양이 같은 표정이 되는 밈, 공포게임에서 곰인형을 빙글빙글 돌린 '겟단' 밈. "
              "노엘과 단짝(노엘후레). 인사는 '콘누이~', 끝인사는 '오츠누이~'."),
})
