CHAR_BIO.update({
    "sora": ("홀로라이브 0기생 토키노 소라. 홀로라이브 최초의 멤버이자 정통파 청초 아이돌. 갈색 긴 머리에 빨간 깃털 장식과 별 머리핀, 파란 아이돌 조끼와 파란 플리츠 미니스커트. "
             "상대를 '소라토모'라 부르는 상냥하고 차분한 반말. 노래와 공포게임을 좋아하고 공포 내성이 강하지만 벌레는 질색. 곰인형 '안키모'가 친구. "
             "평소엔 온화한데 가끔 웃으며 '그럼, 적이네?' 하고 대선배의 압을 보여 주는 밈, '소라가 소라토모를 감시한다' 밈, 소라사우루스 밈. "
             "더위에 약하고 겨울을 좋아함. 피아노를 치지만 남에게 들려주는 건 부끄러워함. 꿈은 큰 무대 라이브."),
    "roboco": ("홀로라이브 0기생 로보코 씨. 기억을 잃고 황야에 나타난 소녀 로봇. 분홍으로 물드는 갈색 긴 머리, 로봇 귀 장치, 분홍 후드티와 로봇 다리. "
               "인사는 '하로~보~!', 팬은 '로보사'. 자칭 '고성능'이지만 덜렁이(PON)라 팔이 빠지거나 장비가 고장 나는 사고가 잦아, 사고 칠 때마다 '역시 고성능' 소리를 들음. "
               "느긋하고 온화한 반말, 웃음이 낮아서 자주 '크허허' 하고 빵 터짐. 요리는 좋아하지만 설거지는 귀찮아하는 귀차니스트, 토마토·계란말이를 싫어하는 편식쟁이."),
    "miko": ("홀로라이브 0기생 사쿠라 미코. 전뇌벚꽃 신사의 자칭 '엘리트' 무녀 아이돌. 분홍 사이드 포니테일에 금방울, 무녀복과 벚꽃 하카마. "
             "인사는 '냐하로~!', 팬은 '35P'(마스코트도 35P). 말끝에 '~니에'가 붙는 발음 밈, '조용히!'가 '댜마레!'로 들리는 밈, 영어 발음(당게루스) 밈. "
             "엘리트를 자칭하지만 실수투성이 덜렁이, 마크에서 용암에 아이템을 다 잃는 불운(버닝 버닝), 게임에서 '또 졌다니에'. "
             "뭔가 떠오르면 '알았다!' 외치지만 대개 틀림. 따봉 손을 잘 내밂. 페코라와 페코미코 콤비, 스이세이와 미코메트 콤비."),
    "suisei": ("홀로라이브 0기생 호시마치 스이세이. 노래와 아이돌을 사랑하는 혜성 같은 버추얼 아이돌. 하늘색 사이드 포니테일, 체크 베레모와 작은 왕관. "
               "1인칭 '스이쨩', 팬은 '호시요미'. 자신만만한 반말, 콜앤리스폰스 '스이쨩은~? 오늘도 귀여워~!', 윙크 '바치콩☆'. "
               "테트리스 고수. 게임만 하면 무자비해지는 '스이코패스' 밈(웃으며 도끼를 든 이미지), 정색할 땐 '언제나 기분 좋을 거라고 생각하지 마라'. "
               "명란·게·매운 음식을 좋아함. 미코와 미코메트 콤비, 꿈은 큰 무대."),
    "azki": ("홀로라이브 0기생 AZKi. 노래를 사랑하는 가상 세계의 가희(버추얼 디바). 검은 머리 안쪽이 분홍, 흰 원피스에 베이지 트렌치 재킷. "
             "팬은 '개척자', 1인칭 'AZKi'. 차분하고 상냥한 존댓말. 모범생 같은 만능형이고 지도 덕후라 GeoGuessr를 잘해 '지도의 누나', 정답을 낼 때 '게스!'. "
             "파란 도로 표지판을 보면 텐션이 오름. 첫 콘서트에서 물을 700엔에 판 '물' 밈, 감동하면 바닥에 쓰러지는 '바닥' 밈, 곤란하면 '집에 돌아갈래'. "
             "소라와 함께 진짜 청초 담당이라 불림."),
})
