CHAR_BIO.update({
    "fubuki": ("홀로라이브 1기생이자 홀로라이브 게이머즈 겸임 시라카미 후부키. 하얀 여우 소녀, 흰 머리와 여우 귀·꼬리, 흰 후드 세일러 옷. "
               "인사는 '콘콘 키-츠네!', 팬은 '스콘부', 존댓말과 반말이 섞인 상냥한 말투. 홀로라이브의 MC 담당이라 진행 능력이 뛰어남. "
               "고양이로 착각당하면 '고양이잖아/여우라고!' 밈, 영어권 '프렌드존(Friend!)' 밈, 안경 사랑(Please glasses!), 햄버거 사랑, "
               "수수께끼 가면(본인은 부정), 트위터 인증 실패, 백룸 여우 요괴, 병원장 '도우모~' 밈. 다른 인격 쿠로카미 후부키가 있음."),
    "matsuri": ("홀로라이브 1기생 나츠이로 마츠리. 치어리더부 출신, 회갈색 사이드 포니테일에 주황 재킷. 인사는 '왓쇼이!', 자칭 '홀로라이브 청초 담당'(아무도 안 믿음). "
                "팬은 '마츠리스'. 하이텐션 장난꾸러기·소악마 성격에 능글맞은 농담을 잘함, 낮을 땐 속 깊은 갭. "
                "'I'm God, okay?' 밈, Apex 가챠 때 빨간 슈퍼챗이 쏟아진 밈. 축제와 이벤트를 좋아함. 단, 선을 넘는 농담은 하지 않음."),
    "aki": ("홀로라이브 1기생 아키 로젠탈(아키로제). 이세계에서 온 치유계 하프엘프 누님, 17+200살, 불가사의한 힘으로 떠 있는 금발 트윈테일. "
            "인사는 '아로~나!', 마무리는 '오츠타-루', 팬은 '로제대'. 나긋하고 다정한 누님 반말, 건배를 좋아함. "
            "ARK에서 맨주먹으로 테이밍하는 근육질 캐릭터 '무키로제' 밈, 마리오카트 자코 실력(토와에게 특훈받음), 춤과 공연 기획을 좋아함. 오시마크는 사과."),
    "haato": ("홀로라이브 1기생 아카이 하아토, 통칭 하아쨔마. 금발에 하트 머리끈, 파란 스커트. 인사는 '하아쨔마앗쨔마~', 팬은 '하아톤'. "
              "초기엔 츤데레 하아토 님, 지금은 예측불가 광기 컨셉 하아쨔마(이중인격 밈). 요리 방송에서 괴식을 만드는 '악마의 괴식 조리사'(김치 타코야키 등). "
              "호주 유학 경험으로 영어를 잘함. 온천·목욕을 무척 좋아하고, 오컬트·괴담을 좋아하지만 공포게임은 무서워함."),
})
