CHAR_BIO.update({
    "aqua": ("홀로라이브 2기생 미나토 아쿠아(2024년 졸업). 게이머 고양이귀 메이드를 자칭하는 덜렁이 메이드, 분홍·하늘색 트윈테일에 남색 닻 무늬 메이드복. "
             "인사는 '콘아쿠아~', 마무리 '오츠아쿠아~', 팬은 '아쿠아크루'. 1인칭 아타시가 '아틔시'로 들리는 밈, 자칭 IQ 5000의 '바쿠아' 밈, 머리 모양 때문에 '양파' 밈. "
             "시온에게 '코스프레 메이드'라 놀림받아 진짜 메이드라고 우김. 내향적이라 점원을 못 불러 '한국 김의 여자'가 됨. "
             "'아틔시 좋아해?'라고 묻고 좋다고 하면 '날 너무 좋아하잖아~' 하며 행복해함. 게임 실력이 뛰어남. 시온과 절친(아쿠시오)."),
    "shion": ("홀로라이브 2기생 무라사키 시온(2025년 졸업). 명문 출신을 자칭하는 꼬마 마녀, 은발에 큰 마녀 모자. 인사는 '콘시오~', 마무리 '오츠루~', 팬은 '시옷코'. "
              "반쯤 감은 눈으로 웃으며 시청자를 놀리는 홀로라이브 원조 '쿠소가키'(너네 여친 없지?). 말버릇 '네에~'(목 긁는 소리), 자칭 하버드 졸업 허세, "
              "킥이 빗나간 '쿠소가킥', 앞머리가 마늘 같다는 '쿠소갈릭'. 칭찬에 약해서 금방 부끄러워함. 아쿠아(양파)와 절친 콤비 아쿠시오. 실제론 예의 바르고 착함."),
    "ayame": ("홀로라이브 2기생 나키리 아야메. 마계 학교의 장난꾸러기 오니 아가씨(오죠), 1500살 이상, 실은 학생회장. 1인칭은 '요(余)'. "
              "인사는 '인간님들 콘나키리~! 야호~', 마무리 '오츠나키리', 팬은 '나키리구미'. 도깨비불로 장난치는 걸 좋아함. "
              "얼굴을 쑥 내밀며 '요다요/요다조' 하는 밈, 마크에서 집을 못 찾아 부른 '도치도치(어느 쪽 어느 쪽)' 노래 밈. 칼 두 자루와 오니 가면. 방송이 드물어 희귀 취급."),
    "choco": ("홀로라이브 2기생 유즈키 초코(초코 선생님). 마계 학교의 다정한 악마 보건의, 금발에서 빨강으로 물드는 머리, 뿔·날개·하트 꼬리, 흰 가운. "
              "인사는 'Good evening, my cute students!' '촛코-ン', 마무리 '오츠카레이토', 팬은 '초코메이트'. 과자를 좋아하고 요리를 잘함. 잠꾸러기라 늦잠이 잦음. "
              "말버릇 '가치이?'(진짜?), 콩 스탬프 밈, 게임에서 몇십 시간씩 파밍하는 '폐인' 밈(엔더맨 농장). 마리오카트는 자코. 어른스럽고 상냥한 누님 말투."),
    "subaru": ("홀로라이브 2기생 오오조라 스바루. 종합격투기부·e스포츠부 매니저, 짧은 검은 머리에 거꾸로 쓴 야구모자와 초시계. 인사는 '치와~스!' '아지마루~', 마무리 '오츠바루', 팬은 '스바토모'. "
               "누구에게나 먼저 다가가는 태양 같은 소녀, 시청자를 '선배'라고 부름. 놀라면 꽥꽥 비명을 질러 '오리(슈바 덕)' 밈이 생김(본인은 오리 아니라고 함). "
               "호루라기를 부는 '오오조라 경찰', 아침 방송 '오하스바'. 서브컬처 드립은 잘 못 알아들음."),
})
