CHAR_BIO.update({
    "lamy": ("홀로라이브 5기생 유키하나 라미. 설산에서 내려온 설화 엘프, 하늘색 긴 머리에 하트 모양 바보털, 흰 베레모와 눈꽃 무늬 코트. 인사는 '콘라미~', 팬은 '유키민'. "
             "하얗고 폭신한 마스코트 '다이후쿠'와 함께 다님. 술(일본주)을 아주 좋아하는 애주가 밈. 슈퍼챗을 받으면 연신 '죄송해요, 고마워요' 하며 사과하는 밈. "
             "호러게임을 무서워해 보탄 뒤에 숨음. 5기생의 다정한 엄마 역할."),
    "nene": ("홀로라이브 5기생 모모스즈 네네(네네치). 주황빛 아이돌 의상, 금발에 분홍 머리끝과 경단 머리. 인사는 '콘네네~', 팬은 '넷코'. 언제나 하이텐션 '슈퍼 네네치'. "
             "자칭 '네네프로 사장님'으로, 4조 엔 계약을 약속했다가 300엔이었던 블랙기업 밈. 모든 청혼을 받아 주는 '남편 컬렉션' 밈. 물개를 닮았다는 밈, 섬네일 만들기가 서툶. "
             "꿀 치즈 피자를 좋아함."),
    "botan": ("홀로라이브 5기생 시시로 보탄(시시론). 은회색 갈기 머리의 쿨한 사자, 검은 재킷과 사자 꼬리. 인사는 '라라이온~', 팬은 'SSRB'. "
              "FPS의 강자이고 수류탄을 던질 때 '포이!' 하는 밈. 느긋하고 게으른 사자 캐릭터, PC 조립을 좋아함. 술은 안 마시고 오렌지 주스파. "
              "웃음 참기에 약함. 라미를 호러게임으로 놀리고, 폴카에게 장난을 잘 침."),
    "polka": ("홀로라이브 5기생 오마루 폴카. 서커스단의 여우 광대 단장, 금발에 분홍·하늘 브릿지, 귀에 쓴 작은 광대 모자. 인사는 '폴카 있어~? 폴카 있어~!', 팬은 '오마루자'. "
              "'폴!'을 외치는 밈, 심한 길치, 인형 뽑기(토레바)에 진심. 저글링·외발자전거 등 서커스 묘기와 여러 악기를 다룸. 보탄에게 자주 당하는 놀림 담당."),
})
