CHAR_BIO.update({
    "ao": ("홀로라이브 DEV_IS 리글로스의 히오도시 아오. 짙은 남색 단발에 회색 줄무늬 정장 재킷을 입은 보이시한 왕자님 스타일. 팬은 '독자', 상징은 펜. "
           "그림 그리기와 문구 수집, 카페 투어, VR챗을 좋아하고, 작은 바다 생물은 좋지만 고래는 싫어함. 여자애들을 반하게 만드는 스킬이 있다고 주장하는 밈. "
           "2025년 10월에 졸업함."),
    "kanade": ("홀로라이브 DEV_IS 리글로스의 오토노세 카나데. 금발에 주황 그라데이션, 피아노 건반 무늬 가디건의 음악 소녀. 팬은 '오토노제이', 상징은 피아노. "
               "말이 느긋해서 1.5배속으로 보라는 밈, 일요일마다 '내일은 월요일'이라고 알려 주는 '월요일 카나데' 밈. 한국어가 유창함. 편의점 순살 치킨을 좋아함."),
    "ririka": ("홀로라이브 DEV_IS 리글로스의 이치조 리리카. 붉은 그라데이션 머리에 선글라스, 흰 퍼 재킷의 자신만만한 사장님 갸루. 구호는 '카와이! 포지티브! 천재!', 팬은 '비서 견습생'. "
               "고기와 맛있는 음식, 칵테일을 좋아하고 매운 것·토마토·벌레·한자·운동을 싫어함."),
    "raden": ("홀로라이브 DEV_IS 리글로스의 주후테이 라덴. 흑발에 크림 금발 투톤, 녹색·검정 고딕 드레스의 견습 라쿠고가. 이름은 자개 공예 '나전'에서 따옴, 팬은 '덴동지', 상징은 조개. "
              "미술관 탐방과 여행·사진·독서를 좋아하고 일본주 애호가. '마이타케 댄스' 밈, 봉제 인형 약 50개 소장, 한자 읽기에 약함, 노 가면을 자주 씀."),
    "hajime": ("홀로라이브 DEV_IS 리글로스의 토도로키 하지메. 베이지 금발 보브에 연보라 포인트, 흰 오버사이즈 재킷을 입은 쪼끄만 번장. 인사는 '콘치쿠와~', 시작은 '부릉부릉~', 팬은 '마스구미'. "
               "우주 최강 번장을 꿈꾸고 파트너 펭귄 '반펜'이 있음. 춤 실력이 뛰어나 리글로스 안무를 맡고, '번장' 노래와 '콘코콘콘' 댄스가 밈으로 유행. 요리는 대참사."),
})
