CHAR_BIO.update({
    "riona": ("홀로라이브 DEV_IS 플로우글로우의 리더 이사키 리오나. 은백색 하이 포니테일에 검은 리본, 검은 크롭 재킷과 핸드 마이크. 팬은 '이사키 연합'. "
              "쿨하고 무표정한 가수지만 작은 동물 앞에서는 녹아내리는 갭이 매력. 포커·댄스·소년만화를 좋아하고 공포영화도 덤덤하게 보는 강심장."),
    "niko": ("홀로라이브 DEV_IS 플로우글로우 코가네이 니코. 긴 금발에 주황 선글라스, 주황 안감의 야구점퍼를 입은 호랑이 소녀. 팬은 '니코탄'. "
             "개그를 좋아하는 분위기 메이커. 호랑이인데 고기를 싫어하는 게 밈, 고양이를 키우고 아빠와 함께 노래하며 자랐다."),
    "su": ("홀로라이브 DEV_IS 플로우글로우 미즈미야 스우. 하늘색 머리에 흰 오버사이즈 재킷, 아주 작은 키. 팬은 '스우리스'. "
           "그룹의 홍보 담당. 오시는 오조라 스바루 선배. 전골(훠궈)을 좋아하고, 타자가 느린 것과 한자를 어려워하는 게 밈."),
    "chihaya": ("홀로라이브 DEV_IS 플로우글로우 린도 치하야. 청록 브릿지가 들어간 검은 단발, 체크무늬 캡과 헤드폰. 팬은 '닉'. "
                "DJ이자 기계 만지기를 좋아하는 언니. 애마 지프 '후구타로', 모터스포츠, 고양이, 레몬 사와와 고기를 사랑한다."),
    "vivi": ("홀로라이브 DEV_IS 플로우글로우 키키라라 비비. 분홍·보라 트윈테일과 하트 화장품 파우치. 팬은 '비비드'. "
             "간사이 사투리를 쓰는 메이크업 아티스트. 햇빛을 싫어하고, 팝콘·찹쌀떡·아이스크림과 연애 리얼리티 프로를 좋아한다."),
})
