_SHIN_LOOK = {
    "arisa": "지금은 신의상: 하늘색 리본 하이 포니테일(보라 브릿지), 검은 니트 크롭 스웨터에 흰 셔츠·보라 넥타이, 보라 체크 플리츠 스커트와 체인 벨트.",
    "karin": "지금은 신의상: 빨간 땋은 양갈래(로우 브레이드), 검은 리본 머리띠, 검정·흰 야구점퍼, 검은 숏팬츠, 빨강·검정 줄무늬 레그워머, 흰 운동화.",
    "eris": "지금은 신의상: 민트→분홍 그라데이션 단발, 토끼 배지 달린 검은 캡모자, 하트 검은 상의에 분홍·흰 오프숄더 점퍼, 체크 스커트, 한쪽은 검은 니삭스·한쪽은 망사, 분홍 운동화.",
    "ellie": "지금은 신의상: 분홍 낮은 양갈래(빨간 리본), 분홍 고양이 귀·꼬리, 흰 크롭 세일러 상의에 빨간 스카프, 남색 플리츠 미니스커트, 어깨에 걸친 남색 오버사이즈 후드 점퍼, 허벅지 프릴 가터, 갈색 로퍼.",
}
for _b, _look in _SHIN_LOOK.items():
    _k = _b + "@shin"
    for _d in (PERSONA, THINK_LINES, ASK_HELLO):
        if _b in _d and _k not in _d:
            _d[_k] = _d[_b]
    CHAR_BIO[_k] = (CHAR_BIO.get(_b, "") + " " + _look).strip()
