class Buddy(QWidget):
    def __init__(self, app, size, x=None, entrance=None, char=None):
        super().__init__()
        self.app = app
        self.char = char or app.pick_char()
        self.setWindowFlags(Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint | Qt.Tool)
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.setAcceptDrops(True)    # 파일 던지기: 파일을 캐릭터 위에 놓으면 요약·정리·변환
        # 기본은 모두 같은 크기. 메뉴에서 '크기 제각각'을 켜면 살짝씩 달라짐
        self.scale = random.uniform(0.8, 1.15) if app.cfg.get("varied", False) else 1.0
        self.S = int(size * self.scale * char_scale(app.cfg, self.char))
        self.setFixedSize(self.S, self.S)
        size = self.S
        self.rope = None
        self.pat = 0
        self.react_next = None       # 부딪힌 뒤 착지해서 할 리액션
        self.grudge = None           # 나를 맞힌 친구
        self.knock_t = 0
        self.goal = None             # 친구에게 다가가기/쫓기/도망
        self.bubble = None; self.bubble_t = 0
        self.pframes, self.pspeed, self.pvx = [0], 10, 0.0
        self.gx = None               # 단체 동작: 모일 위치
        self.gframe = [0]            # 단체 동작: 보여줄 프레임
        self.target_y = 0
        self.face = random.choice([-1, 1])
        self.angle = 0.0
        self.anim = 0
        self.vx = self.vy = 0.0
        self.surface = None          # (left, top, right) 지금 서 있는 곳
        self.edge = 0                # 매달리기/걸터앉기 중인 모서리 방향 (-1 왼쪽, 1 오른쪽)
        self.state, self.t = "air", 0
        self.air_kind = "fall"
        self.fall_from = 0.0
        self.cool = 0                # 마우스·친구 반응 쿨타임
        self.edge_cool = 0
        self.drag = None
        self.after = None            # 상태 끝나고 할 일
        scr = self.scr()
        cx = x if x is not None else random.randint(scr.left() + size, scr.right() - size)
        self.fx = float(cx - size / 2)
        ent = entrance or random.choice(["drop", "drop", "peek", "umbrella", "umbrella", "rope"])
        if app.quiet() and ent in ("drop", "umbrella", "rope"):   # 한 자리에 있기: 하늘에서 안 떨어지고 바닥에서 빼꼼
            ent = "peek"
        if ent == "peek":
            self.fy = float(scr.bottom() - self.S * self.fbottom(F["peek"]))
            self.set("peek", random.randint(90, 160))
        elif ent == "umbrella":
            self.fy = float(scr.top() - size)
            self.set("umbrella")
        elif ent == "rope":
            self.fy = float(scr.top() - size)
            self.rope = Rope(tuple(app.chars[self.char]["rope"].get("rgb", (154, 106, 76))))
            self.set("rope", random.randint(0, 2))   # t = 중간에 멈칫할 횟수
        else:
            self.fy = float(scr.top() - size)
            self.fall_from = self.fy
            self.vx = random.uniform(-1, 1)
        self.move(int(self.fx), int(self.fy))
        self.show()

    # ── 도우미 ─────────────────────────────
    def scr(self):
        return screen_for(self.char).availableGeometry()

    def fbottom(self, f):
        f = self.app.resolve(self.char, f)
        return self.app.chars[self.char]["meta"].get(f, {}).get("bottom", 0.977)

    def ftop(self, f):
        f = self.app.resolve(self.char, f)
        return self.app.chars[self.char]["meta"].get(f, {}).get("top", 0.1)

    @property
    def cx(self):
        return self.fx + self.S / 2

    def feet(self, f=0):
        return self.fy + self.S * self.fbottom(f)

    def set(self, st, t=0, after=None):
        prev = self.state
        self.state, self.t, self.after = st, t, after
        if st not in ("roll",):
            self.angle = 0
        if st == "cry" and prev != "cry" and self.char in CRY_LINES:   # 울 때 캐릭터별 대사
            self.say(random.choice(CRY_LINES[self.char]), 160)

    def stand_on(self, surf):
        self.surface = surf
        self.fy = surf[1] - self.S * self.fbottom(0)

    def surfaces(self):
        scr = self.scr()
        floor = (scr.left() - 9999, scr.bottom(), scr.right() + 9999)
        if not self.app.climb_windows or self.app.quiet():   # 한 자리에 있기: 창 위로 안 올라감
            return [floor]
        return [w for w in self.app.windows if w[1] > scr.top() + 40] + [floor]

    def find_floor(self, cx, feet):
        best = None
        for s in self.surfaces():
            if s[0] + 6 < cx < s[2] - 6 and s[1] >= feet - 14:
                if best is None or s[1] < best[1]:
                    best = s
        return best

    def surface_alive(self):
        if self.surface is None:
            return False
        l, t, r = self.surface
        for s in self.surfaces():
            if abs(s[1] - t) <= 3 and abs(s[0] - l) <= 3 and abs(s[2] - r) <= 3:
                return True
            if abs(s[1] - t) <= 3 and s[0] - 3 <= l and r <= s[2] + 3:
                return True
        return False

    def fall(self, vx=None):
        self.surface = None
        self.air_kind = "fall"
        self.fall_from = self.fy
        if vx is not None:
            self.vx = vx
        self.set("air")

    # ── 매 틱 ─────────────────────────────
    def step(self):
        self.tick_bubble()
        if self.drag is not None:
            return
        if self.state == "tower":               # 인간 탑: 앱이 위치를 정함
            self.anim += 1
            return
        self.cool = max(0, self.cool - 1)
        self.edge_cool = max(0, self.edge_cool - 1)
        self.anim += 1
        st = self.state
        scr = self.scr()

        if st == "air":
            self.vy += GRAVITY
            self.fx += self.vx
            self.fy += self.vy
            if self.air_kind == "thrown":
                self.angle += self.vx * 4
            elif self.air_kind == "knocked":
                if self.knock_t > 0:
                    self.knock_t -= 1                # 처음엔 '헉!' 맞는 모습
                else:
                    self.angle -= self.face * 9      # 그다음 뒤로 빙글빙글
            floor = self.find_floor(self.cx, self.feet() - self.vy)
            if floor and self.vy > 0 and self.feet() >= floor[1]:
                self.stand_on(floor)
                if self.air_kind in ("thrown", "knocked") and self.vy > 6:
                    self.vy *= -0.45; self.vx *= 0.75; self.surface = None
                else:
                    drop = self.fy - self.fall_from
                    self.vy = 0; self.angle = 0
                    if self.air_kind == "hop":
                        self.vx = 0
                        self.set("idle", 20)
                    else:
                        self.vx *= 0.3
                        nxt = None
                        if self.react_next:
                            nxt, self.react_next = self.react_next, None
                        elif drop > 450 and random.random() < 0.4:
                            nxt = "cry"
                        elif self.air_kind == "thrown":
                            nxt = random.choice(["cry", "pout", "pout", None])
                        self.set("land", 22, after=nxt)
                        self.app.landed_near(self)
        elif st == "umbrella":
            self.vy = 1.4
            self.vx = math.sin(self.anim / 25) * 1.2
            self.fx += self.vx
            self.fy += self.vy
            floor = self.find_floor(self.cx, self.feet() - 2)
            if floor and self.feet() >= floor[1]:
                self.stand_on(floor); self.vx = 0
                self.set("cheer" if random.random() < 0.4 else "idle", 60)
        elif st == "rope":
            self.update_rope()
            if self.t > 0 and random.random() < 0.004:
                self.t -= 1
                self.set("rope_pause", random.randint(60, 150), after=self.t)
            else:
                self.fy += 2.2
                floor = self.find_floor(self.cx, self.feet(F["rope"]) - 3)
                if floor and self.feet(F["rope"]) >= floor[1]:
                    self.drop_rope()
                    self.stand_on(floor)
                    self.set("wave" if random.random() < 0.5 else "idle", 70)
        elif st == "rope_pause":
            self.update_rope()
            self.t -= 1
            if self.t <= 0:
                left = self.after
                self.set("rope", left)
        elif st in ("wallclimb", "wallslide"):
            self.wall_step(scr)
        elif st == "balloon":          # 풍선 타고 퇴장
            self.vx = math.sin(self.anim / 30) * 0.8
            self.fx += self.vx
            self.fy -= 1.6
            if self.fy + self.S < scr.top():
                self.app.finished(self)
                return
        elif st == "dig":              # 땅속으로 쏙
            self.fy += 0.7
            self.t -= 1
            if self.t <= 0:
                self.app.finished(self)
                return
        elif st in ("hang", "sit_edge"):
            if not self.surface_alive():
                self.fall(vx=0)
            else:
                self.t -= 1
                if self.t <= 0:
                    self.finish_edge()
        elif st == "climb":
            if not self.surface_alive():
                self.fall(vx=0)
                self.move(int(self.fx), int(self.fy)); return
            self.t -= 1
            if self.t <= 0:
                l, t, r = self.surface
                inside = (r - self.S * 0.45) if self.edge > 0 else (l + self.S * 0.45)
                self.fx = inside - self.S / 2
                self.stand_on(self.surface)
                self.face = -self.edge
                self.edge_cool = 200
                self.set("idle", 30, after="walk_away")
        elif st == "peek":
            self.t -= 1
            if self.t <= 0:
                self.surface = None
                self.air_kind = "hop"; self.fall_from = self.fy
                self.vy = -13; self.vx = random.uniform(-1.5, 1.5)
                self.fy -= self.S * 0.3
                self.set("air")
        else:   # 땅 위 상태
            if not self.surface_alive():
                self.fall()
            else:
                self.ground_step(st, scr)

        # 화면 벽
        if self.state not in ("wallclimb", "wallslide"):
            hit = 0
            if self.fx + self.S * 0.2 < scr.left():
                self.fx = scr.left() - self.S * 0.2; self.vx = abs(self.vx); hit = -1
            if self.fx + self.S * 0.8 > scr.right():
                self.fx = scr.right() - self.S * 0.8; self.vx = -abs(self.vx); hit = 1
            if hit and self.state in ("walk", "run") and self.goal is None and random.random() < 0.35:
                self.start_wall(hit, scr)
        if self.state in ("walk", "run", "roll", "air", "umbrella", "crawl", "balloon", "persona") and abs(self.vx) > 0.2 \
                and not (self.state == "air" and self.air_kind in ("thrown", "knocked")):
            self.face = 1 if self.vx > 0 else -1

    def flush(self):
        """틱마다 한 번: 위치·그림이 실제로 바뀐 경우에만 창을 옮기고 다시 그림 (렉 줄이기)"""
        pos = (int(self.fx), int(self.fy))
        if pos != getattr(self, "_lpos", None):
            self._lpos = pos
            self.move(*pos)
        f = F["fall"] if self.drag is not None else self.frame()
        key = (f, self.face, int(self.angle) if self.angle else 0, self.S, self.app.chars[self.char]["dir"])
        if key != getattr(self, "_lkey", None):
            self._lkey = key
            self.update()

    def ground_step(self, st, scr):
        self.t -= 1
        l, t, r = self.surface
        if not (l < self.cx < r):          # 밀려서 모서리 밖으로!
            self.fall(vx=self.vx)
            return
        if self.app.quiet() and self.app.stay_gate(self):
            return
        if self.goal is not None and self.steer():
            return
        if st == "group":                       # 단체 동작 중: 앱이 조종
            return
        if st == "gather":                      # 단체 동작 자리로 이동
            dx = self.gx - self.cx
            if abs(dx) < 4:
                self.vx = 0; self.state = "group"; self.gframe = [F["walk"][0]]
                return
            self.vx = max(-2.6, min(2.6, dx * 0.08)) or (1 if dx > 0 else -1)
            if abs(self.vx) < 1.0:
                self.vx = 1.0 if dx > 0 else -1.0
            self.face = 1 if dx > 0 else -1
            self.fx += self.vx
            return
        if st == "train":                       # 기차놀이: 앞사람 따라가기
            lead, k = self.gx
            if lead not in self.app.buddies or lead.surface != self.surface:
                self.set("idle", 30); return
            tx = lead.cx - lead.face * self.S * 0.55 * k
            dx = tx - self.cx
            self.vx = max(-2.4, min(2.4, dx * 0.1))
            self.face = lead.face
            l2, t2, r2 = self.surface
            if l2 + 6 < self.cx + self.vx < r2 - 6:
                self.fx += self.vx
            if self.t <= 0:
                self.set("cheer", 60)
            return
        if st == "persona" and self.pvx:        # 움직이는 개성 동작(청소·잠입 등)
            nx = self.cx + self.vx
            if not (l + 6 < nx < r - 6):
                self.vx = -self.vx
            else:
                self.fx += self.vx
        if st == "push":
            other = self.app.ahead(self)
            if other is None:
                self.t = min(self.t, 0)
            else:
                other.fx += self.vx
                other.face = self.face
                if other.state != "pushed":
                    other.vx = 0
                    other.set("pushed", 30)
                other.t = 30
            nx = self.cx + self.vx
            if l + 6 < nx < r - 6:
                self.fx += self.vx
        if st in ("walk", "run", "roll", "crawl"):
            if st == "walk" and self.goal is None and random.random() < 0.02:
                other = self.app.ahead(self)
                if other and other.state in ("idle", "sleep", "nap", "read", "milk", "pout", "eat", "wiggle"):
                    self.vx = self.face * 0.6
                    self.set("push", random.randint(80, 200))
                    return
            nx = self.cx + self.vx
            l, t, r = self.surface
            if not (l + 6 < nx < r - 6):          # 모서리 도착!
                if self.goal is not None:          # 놀이 중엔 모서리에서 그냥 돌아서기
                    self.vx = -self.vx
                    return
                self.at_edge(1 if self.vx > 0 else -1)
                return
            self.fx += self.vx
            if st == "run" and self.goal is None and random.random() < 0.004:      # 꽈당!
                self.vx = 0
                self.set("trip", 70, after=random.choice(["cry", "pout", None, None]))
                return
            if st == "roll":
                self.angle += self.vx * 360 / (math.pi * self.S * 0.75)
        if self.t <= 0:
            nxt, self.after = self.after, None
            if callable(nxt):
                try:
                    nxt()
                except Exception:
                    pass
                if self.state == "seq" and self.t <= 0:
                    self.choose()
                return
            if nxt == "cry":
                self.set("cry", random.randint(90, 160))
            elif nxt == "sleep":
                self.set("sleep", random.randint(400, 1200))
            elif nxt == "walk_away":
                self.vx = self.face * random.uniform(0.8, 1.3)
                self.set("walk", random.randint(80, 200))
            elif nxt == "hop":
                self.hop()
            elif nxt == "nap":
                self.set(random.choice(["sleep", "nap"]), random.randint(400, 1200))
            elif nxt == "pout":
                self.set("pout", random.randint(100, 200))
            elif nxt in ("bump", "dizzy", "faint", "rub"):
                self.vx = 0
                t = {"bump": 100, "dizzy": 160, "faint": 230, "rub": 130}[nxt]
                follow = {"faint": "dizzy", "dizzy": "grumble", "bump": "grumble", "rub": "grumble"}[nxt]
                self.set(nxt, t, after=follow)
            elif nxt == "grumble":            # 화내며 쫓아가거나, 울거나, 삐지거나
                g = self.grudge
                if g in self.app.buddies and g.surface == self.surface and random.random() < 0.55:
                    self.face = 1 if g.cx > self.cx else -1
                    self.vx = 0
                    self.set("angry", 110, after="chase")
                else:
                    self.grudge = None
                    self.set(random.choice(["cry", "pout", "pout"]), random.randint(90, 150))
            elif nxt == "chase":
                g, self.grudge = self.grudge, None
                if g in self.app.buddies and g.surface == self.surface:
                    self.face = 1 if g.cx > self.cx else -1
                    self.vx = self.face * 3.8
                    self.set("run", 80)
                else:
                    self.choose()
            elif nxt == "caught":
                self.set("cheer", 80)
            elif nxt == "bigjump":
                self.hop(17)
            else:
                self.choose()
        if self.goal is None and st not in ("group", "gather", "train", "seq"):   # 놀이 중엔 커서 반응으로 끊기지 않게
            self.near_cursor()
            self.check_pat()
        if st == "pushed" and self.t <= 0:
            self.set("pout", 60)

    def say(self, text, ticks=150, force=False, sticky=False):
        if not force and ((self.bubble and self.bubble.sticky) or getattr(self, "say_lock", 0) > 0):
            return                                   # Claude 가 띄운 말풍선은 사용자가 닫을 때까지 그대로
        if not force and not self.app.cfg.get("bubbles", True):
            return
        if not sticky:
            text = voice_filter(f"{self.char}@{self.app.outfit.get(self.char)}", text)
        if self.bubble:
            self.bubble.close()
        self.bubble = Bubble(text, sticky, on_close=self.bubble_closed if sticky else None)
        self.bubble_t = ticks
        self.place_bubble()
        self.bubble.show()

    def bubble_closed(self):
        self.bubble = None; self.bubble_t = 0; self.say_lock = 0

    def place_bubble(self):
        if not self.bubble:
            return
        top = self.fy + self.S * self.ftop(self.frame()) - self.bubble.height() + 4
        self.bubble.move(int(self.cx - self.bubble.width() / 2), int(top))

    def tick_bubble(self):
        if getattr(self, "say_lock", 0) > 0:
            self.say_lock -= 1
        if self.bubble:
            if not self.bubble.sticky:
                self.bubble_t -= 1
            if self.bubble_t <= 0 and not self.bubble.sticky:
                self.bubble.close(); self.bubble = None
            else:
                self.place_bubble()

    def do_persona(self, idx=None):
        """캐릭터 고유 동작 (6번 시트)"""
        lst = self.app.chars[self.char].get("persona") or []
        if not lst:
            return False
        if idx is None:
            item = random.choices(lst, weights=[x[3] for x in lst])[0]
        else:
            item = lst[idx % len(lst)]
        frames, speed, dur, _, vx, lines = item
        self.pframes, self.pspeed = frames, speed
        self.pvx = vx
        self.vx = (self.face or 1) * vx
        self.set("persona", random.randint(*dur))
        self.say(random.choice(lines))
        # 시부키가 "다들 모여!" 하면 단체 놀이 시작
        if (self.char, frames[0]) in SUMMON and self.app.team:
            QTimer.singleShot(1500, lambda: self.app.group_event(leader=self))
        if self.char == "toa" and frames[0] in (52, 58):      # 퇴마 드립: 유령·저주인형은 도망!
            for o in self.app.buddies:
                if o.char in ("hiyori", "mary") and o.surface == self.surface and o.surface \
                        and abs(o.cx - self.cx) < self.S * 4 and o.state in ("idle", "walk", "read", "milk", "cheer") \
                        and o.goal is None:
                    o.say("히익! 퇴마당한다!" if o.char == "hiyori" else "냐악! 저리 가 냐!", 90)
                    o.go_to(self, "flee", ticks=110)
        if self.char in ("hiyori", "rang") and frames[0] in ((52,) if self.char == "hiyori" else (58,)):
            for o in self.app.buddies:                         # 뿌! / 어흥! 에 깜짝
                if o is not self and o.surface == self.surface and o.surface \
                        and abs(o.cx - self.cx) < self.S * 2.5 and o.state in ("idle", "walk", "read", "milk") \
                        and o.goal is None:
                    o.vx = 0; o.set("surprise", 50)
        if self.char == "riko" and frames == [56]:      # 점프킹: 웅크렸다가 크게 점프
            self.after = "bigjump"
        return True

    def has_frame(self, f):
        try:
            return os.path.exists(os.path.join(self.app.chars[self.char]["dir"], f"{f}.png"))
        except Exception:
            return False

    def play_seq(self, seq, after=None):
        """[(프레임, 틱), ...] 을 한 번 재생하고 after(함수 또는 다음 상태)"""
        self.vx = 0
        self.seqf = [(f, max(1, int(d))) for f, d in seq]
        self.seq_total = sum(d for _, d in self.seqf)
        self.set("seq", self.seq_total, after=after)

    def say_later(self, ticks, text):
        QTimer.singleShot(int(ticks * TICK), lambda: self.say(text, 110) if self in self.app.buddies else None)

    def do_shoot(self):
        """니케: 뒷모습으로 총 쏘기 (대기 → 조준 → 연사 → 장전 → 연사 → 버스트 → 뒤돌아 브이)"""
        if not self.has_frame(F["shoot_ready"]):
            return False
        a, b = F["shoot_fire"]
        fire = lambda n, sp=6: [(a, sp), (b, sp)] * n
        seq = [(F["shoot_ready"], 30), (F["shoot_aim"], 26)] + fire(random.randint(8, 14)) \
            + [(F["shoot_reload"], 45)] + fire(random.randint(6, 10))
        if random.random() < 0.35:
            seq += [(F["shoot_cover"], 50)] + fire(5)
        t_burst = sum(d for _, d in seq)
        seq += [(F["burst"], 70), (F["shoot_end"], 70)]
        key = f"{self.char}@{self.app.outfit.get(self.char)}"
        lines = SHOOT_LINES.get(key) or SHOOT_LINES.get(self.char) or ("사격 개시!", "장전!", "버스트!", "클리어!")
        self.say(lines[0], 90)
        reload_t = 56 + 2 * 6 * 8
        self.say_later(reload_t, lines[1])
        self.say_later(t_burst, lines[2])
        self.say_later(t_burst + 70, lines[3])
        self.play_seq(seq)
        return True

    def go_to(self, who, mode="approach", arrive=None, ticks=600, speed=None):
        """친구에게 다가가기(approach) / 쫓기(chase) / 도망치기(flee)"""
        if self.app.quiet():     # 한 자리에 있기: 다가가기·쫓기·도망 안 함
            return
        sp = speed or {"approach": 1.4, "chase": 3.6, "flee": 3.3}[mode]
        self.goal = {"who": who, "mode": mode, "arrive": arrive, "until": ticks, "speed": sp}
        d = 1 if who.cx > self.cx else -1
        if mode == "flee":
            d = -d
        self.vx = d * sp
        self.set("run" if sp > 2.5 else "walk", ticks)

    def steer(self):
        g = self.goal
        o = g["who"]
        g["until"] -= 1
        cur = o is CURSOR
        if (not cur and (o not in self.app.buddies or o.surface != self.surface)) or g["until"] <= 0 \
                or self.state not in ("walk", "run"):
            self.goal = None
            return False
        dx = o.cx - self.cx
        d = 1 if dx > 0 else -1
        if g["mode"] == "flee":
            self.vx = -d * g["speed"]
        else:
            self.vx = d * g["speed"]
            if abs(dx) < (self.S + o.S) * (0.22 if g["mode"] == "chase" else 0.35):
                self.goal = None
                self.vx = 0
                self.face = d
                if g["arrive"]:
                    g["arrive"](self, o)
                else:
                    self.set("idle", 40)
                return True
        return False

    def check_pat(self):
        """커서를 머리 위에 가만히 올려두면 쓰담쓰담"""
        if self.state in ("sleep", "nap", "air", "dig", "balloon", "walk", "run", "roll", "crawl", "hang", "climb",
                          "rope", "rope_pause", "wallclimb", "push") \
                or getattr(self, "goal", None) is not None or abs(self.vx) > 0.5 or QApplication.mouseButtons():
            self.pat = 0; return                         # 도망·쫓기·이동 중엔 쓰담 안 됨 (지나가다 커서에 닿아도 X)
        c = QCursor.pos()
        if self.geometry().contains(c):
            self.pat += 1
            if self.pat == 45:
                self.vx = 0; self.cool = 300
                self.set("happy", 150)
                self.app.touch(self, "pat")
            elif self.pat > 45 and self.state == "happy":
                self.t = max(self.t, 30)          # 계속 쓰다듬으면 계속 행복
        else:
            self.pat = 0

    # ── 밧줄 ─────────────────────────────
    def update_rope(self):
        if self.rope:
            info = self.app.chars[self.char]["rope"]
            rx = info.get("x", 0.5)                       # 그림 속 밧줄 위치 (좌우 반전 반영)
            x = self.fx + self.S / 2 + self.face * (self.S * rx - self.S / 2)
            top_y = self.fy + self.S * self.ftop(F["rope"]) + 3
            self.rope.place(x, self.scr().top() - 5, top_y, self.S * info.get("w", 0.03))

    def closeEvent(self, e):
        """펫이 화면에서 빠질 때(환경설정에서 빼기·퇴장 등) 말풍선도 같이 정리 — 안 하면 말풍선만 허공에 남음"""
        try:
            if self.bubble:
                bb, self.bubble = self.bubble, None
                bb.close()
            self.drop_rope()
        except Exception:
            pass
        super().closeEvent(e)

    def drop_rope(self):
        if self.rope:
            self.rope.close(); self.rope = None

    # ── 화면 벽 타기 ──────────────────────
    def start_wall(self, side, scr):
        self.edge = side
        self.face = side
        m = self.app.chars[self.char]["meta"].get(F["wallclimb"][0], {})
        right = m.get("right", 0.95)
        if side > 0:
            self.fx = scr.right() - self.S * right
        else:
            self.fx = scr.left() - self.S * (1 - right)
        self.surface = None
        self.vx = 0
        self.target_y = self.fy - random.randint(80, 600)
        self.set("wallclimb", 0)

    def wall_step(self, scr):
        if self.state == "wallclimb":
            if self.t > 0:            # 잠깐 쉬는 중
                self.t -= 1
                return
            self.fy -= 1.3
            if random.random() < 0.006:
                self.t = random.randint(40, 100)
            if self.fy <= max(self.target_y, scr.top() + 10):
                r = random.random()
                if r < 0.55:
                    self.set("wallslide")
                elif r < 0.8:
                    self.fall(vx=-self.edge * 2)
                else:
                    self.t = random.randint(80, 200)
                    self.target_y = self.fy - random.randint(50, 200)
        else:   # 미끄러져 내려오기
            self.fy += 3.0
            floor = self.find_floor(self.cx, self.feet() - 4)
            if floor and self.feet() >= floor[1]:
                self.stand_on(floor)
                self.fx -= self.edge * self.S * 0.3
                self.face = -self.edge
                self.set("idle", 40, after="walk_away")

    # ── 모서리 행동: 매달리기 / 걸터앉기 / 돌아서기 / 떨어지기 ──
    def at_edge(self, d):
        l, t, r = self.surface
        is_floor = r - l > 5000
        if is_floor or self.edge_cool > 0:
            self.vx = -self.vx
            return
        r_ = random.random()
        if self.state == "roll" or r_ < 0.2:
            self.fx += self.vx * 3
            self.fall()
        elif r_ < 0.55:
            self.edge = d
            ex = r if d > 0 else l
            self.fx = ex + d * self.S * 0.12 - self.S / 2
            self.fy = t - self.S * self.ftop(F["hang"]) - 4
            self.face = -d
            self.vx = 0
            self.set("hang", random.randint(120, 320))
        elif r_ < 0.8:
            self.edge = d
            ex = r if d > 0 else l
            self.fx = ex - self.S / 2
            top, bot = self.ftop(F["sit_edge"]), self.fbottom(F["sit_edge"])
            self.fy = t - self.S * (top + (bot - top) * SIT_HIP)
            self.face = d
            self.vx = 0
            self.set("sit_edge", random.randint(250, 700))
        else:
            self.vx = -self.vx
            self.edge_cool = 60

    def finish_edge(self):
        if self.state == "hang":
            if random.random() < 0.6:
                top, bot = self.ftop(F["climb"]), self.fbottom(F["climb"])
                self.fy = self.surface[1] - self.S * (top + (bot - top) * 0.45)
                self.set("climb", 40)
            else:
                self.fall(vx=self.edge * 0.5)
        else:   # 걸터앉기 끝 → 돌아서 들어가기
            l, t, r = self.surface
            self.fx = (r - self.S * 0.45 if self.edge > 0 else l + self.S * 0.45) - self.S / 2
            self.stand_on(self.surface)
            self.face = -self.edge
            self.edge_cool = 200
            self.vx = self.face * 1.0
            self.set("walk", random.randint(80, 200))

    # ── 다음 행동 고르기 ─────────────────────
    def choose(self):
        if self.app.cfg.get("sleep_mode", False) and self.surface:   # 수면 모드: 구석에서 깨울 때까지 쿨쿨
            hx = self.app.stay_home(self)
            if hx is not None:
                self.fx = float(hx - self.S / 2)
                self.move(int(self.fx), int(self.fy))
            self.vx = 0
            self.set("sleep", 600)
            return
        if self.app.quiet() and self.surface:
            hx = self.app.stay_home(self)
            if hx is not None and abs(self.cx - hx) > max(20, self.S * 0.2):
                self.fx = float(hx - self.S / 2); self.vx = 0       # 걷지 않고 자리로 쏙
                self.move(int(self.fx), int(self.fy))
                self.set("idle", random.randint(60, 160))
                return
        h = hour()
        night = h >= 23 or h < 6
        lunch = 12 <= h < 13
        w = {
            "walk": 30, "run": 8, "roll": 10, "idle": 10, "hop": 6,
            "cheer": 5, "wave": 4, "eat": 12 if lunch else 4,
            "yawn": 10 if night else 3, "sleep": 14 if night else 4,
            "dance": 5, "pout": 2,
            "crawl": 6, "wiggle": 4, "read": 4, "sing": 3, "kiss": 2,
            "milk": 8 if 7 <= h < 10 else 3, "exit": 1.2,
            "persona": 22 if self.app.chars[self.char].get("persona") else 0,
            "shoot": 7 if self.has_frame(F["shoot_ready"]) else 0,
        }
        if self.app.quiet():
            for _k in ("walk", "run", "roll", "hop", "crawl", "exit"):
                w[_k] = 0
            w["idle"] = 30
        pick = random.choices(list(w), weights=list(w.values()))[0]
        d = random.choice([-1, 1])
        if pick == "walk":
            self.vx = d * random.uniform(0.8, 1.4); self.set("walk", random.randint(120, 400))
        elif pick == "run":
            self.vx = d * random.uniform(3.0, 4.0); self.set("run", random.randint(50, 120))
        elif pick == "roll":
            self.vx = d * random.uniform(2.5, 4.5); self.set("roll", random.randint(60, 180))
        elif pick == "hop":
            self.hop()
        elif pick == "yawn":
            self.vx = 0; self.set("yawn", 90, after="nap")
        elif pick == "persona":
            self.do_persona()
        elif pick == "shoot":
            self.do_shoot()
        elif pick == "crawl":
            self.vx = d * 0.55; self.set("crawl", random.randint(150, 400))
        elif pick == "exit":
            self.app.leave(self, travel=True)
        else:
            self.vx = 0
            t = {"idle": (60, 180), "cheer": (60, 110), "wave": (70, 130),
                 "eat": (200, 400), "sleep": (400, 1200), "dance": (150, 400),
                 "pout": (100, 200), "wiggle": (100, 250), "read": (300, 700),
                 "sing": (200, 400), "kiss": (60, 100), "milk": (150, 300)}[pick]
            self.set(pick, random.randint(*t))

    def hop(self, power=10):
        self.air_kind = "hop"
        self.fall_from = self.fy
        self.vy = -power
        self.vx = self.face * random.uniform(0, 1.5)
        self.surface = None
        self.set("air")

    def near_cursor(self):
        if _rest_on(self.app):
            return  # 제자리 모드: 커서 따라 뛰어가거나 비켜 달아나지 않고 하던 놀이 계속
        if self.app.cfg.get("cursor_avoid", True):
            # 커서 피해 다니기: 움직이는 커서가 가까이 오면 반대쪽으로 비켜 줌 (가만히 둔 커서 위에선 쓰담쓰담 그대로)
            if self.drag is not None or not self.surface or self.state not in AVOID_STATES:
                return
            if QApplication.keyboardModifiers() & (Qt.ControlModifier | Qt.ShiftModifier):
                return  # Ctrl/Shift 누른 채면 안 도망감 → 머리에 올려서 쓰담쓰담 가능
            c = QCursor.pos(); now = time.time()
            if getattr(self.app, "_av_pos", None) != c:
                self.app._av_pos = c; self.app._av_t = now
            if now - getattr(self.app, "_av_t", 0) > 1.0:
                return
            dx = c.x() - self.cx
            r = max(120, self.S * 0.9)
            if abs(dx) < r and abs(c.y() - (self.fy + self.S / 2)) < r:
                d = -1 if dx > 0 else 1
                self.face = d; self.vx = d * 3.6
                self.set("run", 30)
                _now = time.time()
                if _now - getattr(self, "_flee_t", 0) > 5 and random.random() < 0.45:
                    self._flee_t = _now
                    _base = self.char.split("@")[0]
                    self.say(random.choice(FLEE_LINES.get(_base) or FLEE_DEFAULT), 80)
            return
        if self.cool or self.state in ("sleep", "nap", "cry", "eat", "push", "pushed", "dig", "balloon",
                                       "bump", "dizzy", "faint", "rub", "angry", "catch"):
            return
        c = QCursor.pos()
        dx = c.x() - self.cx
        if abs(dx) < 170 and abs(c.y() - (self.fy + self.S / 2)) < 170:
            self.cool = 500
            self.face = 1 if dx > 0 else -1
            r = random.random()
            if r < 0.45:
                self.vx = 0; self.set("wave", 90)
            elif r < 0.7:
                self.vx = self.face * 3.5; self.set("run", 40)     # 쪼르르 다가오기
            elif r < 0.8:
                self.vx = 0; self.set("cheer", 70)
            elif r < 0.92:
                self.vx = 0; self.set("kiss", 70)

    def greet(self, other_dir):
        if self.cool or self.state not in ("walk", "idle"):
            return
        self.cool = 600
        self.face = other_dir
        self.vx = 0
        self.set(random.choice(["wave", "cheer", "kiss"]), 90)

    # ── 그리기 ────────────────────────────
    def frame(self):
        st = self.state
        if st == "air":
            if self.air_kind == "thrown":
                return F["ball"]
            if self.air_kind == "knocked":
                return F["hit"] if self.knock_t > 0 else F["knocked"]
            return F["jump"] if self.air_kind == "hop" else F["fall"]
        if st == "walk":
            return F["walk"][(self.anim // 8) % 4]
        if st == "run":
            return F["run"][(self.anim // 5) % 2]
        if st == "roll":
            return F["ball"]
        if st == "idle":
            return F["walk"][0]
        if st == "umbrella":
            return F["umbrella"][(self.anim // 20) % 2]
        if st in ("rope", "rope_pause"):
            return F["rope"]
        if st == "wallclimb":
            return F["wallclimb"][(self.anim // 14) % 2] if self.t <= 0 else F["wallclimb"][0]
        if st == "dance":
            return F["dance"][(self.anim // 12) % 2]
        if st == "crawl":
            return F["crawl"][(self.anim // 14) % 2]
        if st == "persona":
            return self.pframes[(self.anim // self.pspeed) % len(self.pframes)]
        if st == "seq":                          # 정해진 순서대로 한 번 재생(사격·변신)
            k, acc = self.seq_total - max(self.t, 0), 0
            for f, d in self.seqf:
                acc += d
                if k < acc:
                    return f
            return self.seqf[-1][0]
        if st in ("group", "tower"):
            return self.gframe[(self.anim // 12) % len(self.gframe)]
        if st == "gather":
            return F["walk"][(self.anim // 8) % 4]
        if st == "train":
            return F["train"][(self.anim // 9) % 2] if abs(self.vx) > 0.3 else F["train"][0]
        if st == "wiggle":
            return F["wiggle"][(self.anim // 10) % 2]
        v = F.get(st, 0)
        return v[0] if isinstance(v, list) else v

    def paintEvent(self, e):
        f = self.frame()
        if self.drag is not None:
            f = F["fall"]
        p = QPainter(self)
        ball = f == F["ball"] or (f == F["knocked"] and self.state == "air")
        if ball and self.angle:                       # 굴러갈 때만 회전 (그 외에는 미리 줄여 둔 그림을 그대로)
            pm = self.app.pix(f, self.char)
            p.setRenderHint(QPainter.SmoothPixmapTransform)
            cy = self.S * (self.ftop(f) + self.fbottom(f)) / 2
            p.translate(self.S / 2, cy)
            p.rotate(self.angle)
            p.scale(self.face, 1)
            p.drawPixmap(int(-self.S / 2), int(-cy), self.S, self.S, pm)
        else:
            p.drawPixmap(0, 0, self.app.spix(f, self.char, self.S, self.face, self.devicePixelRatioF()))

    # ── 파일 던지기 ────────────────────────────
    def _drop_paths(self, e):
        md = e.mimeData()
        if not md.hasUrls():
            return []
        return [u.toLocalFile() for u in md.urls() if u.isLocalFile() and u.toLocalFile()]

    def dragEnterEvent(self, e):
        if self._drop_paths(e):
            e.acceptProposedAction()
            if self.surface and self.state not in ("sleep", "nap"):
                self.vx = 0; self.set("surprise", 60)
            self.say(random.choice(DROP_LINES["hover"]), 80)
        else:
            e.ignore()

    def dragMoveEvent(self, e):
        e.acceptProposedAction() if self._drop_paths(e) else e.ignore()

    def dropEvent(self, e):
        paths = self._drop_paths(e)
        if not paths:
            return
        e.acceptProposedAction()
        QTimer.singleShot(50, lambda: self.app.file_drop(self, paths))

    # ── 마우스 ────────────────────────────
    def mousePressEvent(self, e):
        if e.button() == Qt.LeftButton and getattr(self, "hiding", False):   # 숨바꼭질: 찾았다!
            self.app.hs_found(self)
            return
        if e.button() == Qt.LeftButton:
            self.drag = e.globalPos() - QPoint(int(self.fx), int(self.fy))
            self.drop_rope()
            if self.state in ("group", "gather", "tower", "train"):
                self.app.group_break()
            self.moved = False
            self.trail = [e.globalPos()]
            self.angle = 0
            self.update()

    def mouseMoveEvent(self, e):
        if self.drag is None:
            return
        if not self.moved and (e.globalPos() - self.trail[0]).manhattanLength() < 6:
            return                                   # 손 떨림 정도는 '클릭'으로 봄
        self.moved = True
        p = e.globalPos() - self.drag
        self.fx, self.fy = float(p.x()), float(p.y())
        self.trail = (self.trail + [e.globalPos()])[-5:]
        self.move(p)

    def mouseReleaseEvent(self, e):
        if self.drag is None or e.button() != Qt.LeftButton:
            return
        self.drag = None
        if not (self.moved and len(self.trail) >= 2):
            # 톡! → 따닥(더블클릭)일 수도 있으니 잠깐 기다렸다가 폴짝 (그 사이 제자리에 가만히)
            self.vx = 0; self.goal = None
            tok = object(); self._click = tok
            QTimer.singleShot(QApplication.doubleClickInterval() + 40,
                              lambda: self._single_click() if getattr(self, "_click", None) is tok else None)
            return
        self.surface = None
        self.fall_from = self.fy
        if self.moved and len(self.trail) >= 2:
            d = self.trail[-1] - self.trail[0]
            n = len(self.trail)
            self.vx = max(-25, min(25, d.x() / n))
            self.vy = max(-25, min(25, d.y() / n))
            self.air_kind = "thrown" if abs(self.vx) + abs(self.vy) > 7 else "fall"
            if self.air_kind == "thrown":
                self.app.add_aff(self, -1)
            self.set("air")
        else:   # 톡! → 폴짝 + 만세
            self.hop(11)
            self.after = None

    def _single_click(self):
        self._click = None
        if self.drag is not None or self not in self.app.buddies:
            return
        if self.surface is None or self.state in self.app.BUSY:   # 공중·매달린 중이면 예전처럼 폴짝
            self.app.touch(self, "poke")
            self.surface = None
            self.fall_from = self.fy
            self.hop(11)
            self.after = None
            return
        # 땅 위에서 톡: 폴짝 뛰지 않고 제자리에서 반응 (낯가리면 깜짝, 친하면 반가워함) — 삐짐은 touch 가 처리
        if self.state == "pout":                       # 삐진 중엔 계속 찔러도 흥! 하고 고개 돌린 채
            self.set("pout", 120)
            self.say("흥!", 60)
            return
        lv = self.app.aff_level(self.app.aff(self.char))
        self.vx = 0; self.goal = None
        self.set(("surprise", "surprise", "wave", "happy", "happy")[lv], 70)
        self.app.touch(self, "poke")

    def mouseDoubleClickEvent(self, e):
        self._click = None                            # 첫 번째 '톡' 폴짝은 취소
        self.drag = None
        self.vx = 0
        if self.surface is None:
            self.stand_on(self.find_floor(self.cx, self.feet()) or self.surfaces()[-1])
        self.set("cheer", 90)
        if self.app.cfg.get("ask_dbl", True):          # 따닥 → 이 아이에게 Claude 로 물어보기
            QTimer.singleShot(250, lambda: self.app.ask_claude(self))

    def contextMenuEvent(self, e):
        self.app.menu(e.globalPos(), self)



SIZES = [("아주 작게", 64), ("작게", 100), ("보통", 136), ("크게", 190), ("아주 크게", 260), ("왕 크게", 340), ("거대", 480), ("초거대", 640)]


def settings_qss():
    """환경설정 창 분홍 테마 (체크 표시 그림은 처음 한 번 임시 폴더에 그려 둠)"""
    import tempfile
    tmp = tempfile.gettempdir()
    ck = os.path.join(tmp, "minibuddies_check.png")
    up, dn = os.path.join(tmp, "minibuddies_up.png"), os.path.join(tmp, "minibuddies_dn.png")
    for path, pts in ((up, ((2, 10), (8, 3), (14, 10))), (dn, ((2, 3), (8, 10), (14, 3)))):
        if not os.path.exists(path):
            try:
                from PyQt5.QtGui import QColor, QPolygon
                pm = QPixmap(16, 13); pm.fill(Qt.transparent)
                pa = QPainter(pm); pa.setRenderHint(QPainter.Antialiasing)
                pa.setPen(Qt.NoPen); pa.setBrush(QColor("#d0588a"))
                pa.drawPolygon(QPolygon([QPoint(x, y) for x, y in pts])); pa.end()
                pm.save(path)
            except Exception:
                pass
    if not os.path.exists(ck):
        try:
            from PyQt5.QtGui import QPen, QColor
            pm = QPixmap(32, 32); pm.fill(Qt.transparent)
            pa = QPainter(pm); pa.setRenderHint(QPainter.Antialiasing)
            pa.setPen(QPen(QColor("white"), 5, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
            pa.drawPolyline(QPoint(7, 17), QPoint(13, 23), QPoint(25, 9)); pa.end()
            pm.save(ck)
        except Exception:
            pass
    ck, up, dn = (x.replace("\\", "/") for x in (ck, up, dn))
    return """
QDialog{background:#fff4f8;}
QDialog QWidget{font-family:'Malgun Gothic','맑은 고딕',sans-serif;font-size:10pt;color:#4a3a44;}
QTabWidget::pane{border:1px solid #f3c6d8;border-radius:12px;background:#fffafc;top:-1px;}
QTabBar::tab{background:#fbe3ee;color:#9a4d6e;border:1px solid #f3c6d8;border-bottom:none;padding:7px 18px;margin-right:3px;
  border-top-left-radius:10px;border-top-right-radius:10px;}
QTabBar::tab:selected{background:#fffafc;color:#d0588a;font-weight:bold;}
QTabBar::tab:hover:!selected{background:#f7d3e3;}
QGroupBox{border:1px solid #f3c6d8;border-radius:12px;margin-top:16px;padding:12px 8px 8px;background:#ffffff;}
QGroupBox QGroupBox{background:#fff8fb;}
QGroupBox::title{subcontrol-origin:margin;left:14px;padding:0 6px;color:#d0588a;font-weight:bold;}
QPushButton{background:#fbe3ee;color:#b0476f;border:1px solid #f3c6d8;border-radius:9px;padding:5px 14px;min-height:20px;}
QPushButton:hover{background:#f7cfe0;}
QPushButton:pressed{background:#f0b7cf;}
QPushButton:default{background:#e86a9b;color:white;border-color:#e86a9b;font-weight:bold;}
QPushButton:disabled{color:#c9a9b8;background:#f8eef3;}
QCheckBox{spacing:8px;}
QCheckBox::indicator{width:17px;height:17px;border:1px solid #e3a3bf;border-radius:5px;background:white;}
QCheckBox::indicator:hover{border-color:#e86a9b;}
QCheckBox::indicator:checked{background:#e86a9b;border-color:#e86a9b;image:url(%(ck)s);}
QComboBox,QSpinBox,QTimeEdit,QLineEdit{background:white;border:1px solid #f0c3d6;border-radius:8px;padding:3px 8px;min-height:22px;}
QComboBox:focus,QSpinBox:focus,QLineEdit:focus,QTimeEdit:focus{border-color:#e86a9b;}
QComboBox::drop-down{border:none;width:22px;}
QComboBox::down-arrow{image:url(%(dn)s);width:12px;height:9px;margin-right:8px;}
QAbstractSpinBox::up-button,QAbstractSpinBox::down-button{width:16px;border:none;background:transparent;}
QAbstractSpinBox::up-arrow{image:url(%(up)s);width:10px;height:7px;}
QAbstractSpinBox::down-arrow{image:url(%(dn)s);width:10px;height:7px;}
QComboBox QAbstractItemView{background:white;border:1px solid #f0c3d6;selection-background-color:#fbe3ee;selection-color:#b0476f;}
QSlider::groove:horizontal{height:6px;background:#f3d9e5;border-radius:3px;}
QSlider::sub-page:horizontal{background:#e86a9b;border-radius:3px;}
QSlider::handle:horizontal{background:white;border:2px solid #e86a9b;width:14px;margin:-6px 0;border-radius:9px;}
QScrollArea{background:transparent;border:none;}
QScrollArea > QWidget > QWidget{background:transparent;}
QScrollBar:vertical{background:transparent;width:10px;margin:2px;}
QScrollBar::handle:vertical{background:#f0c3d6;border-radius:4px;min-height:30px;}
QScrollBar:horizontal{background:transparent;height:10px;margin:2px;}
QScrollBar::handle:horizontal{background:#f0c3d6;border-radius:4px;min-width:30px;}
QScrollBar::add-line,QScrollBar::sub-line{height:0;width:0;}
QListWidget,QTableWidget,QTextBrowser{background:white;border:1px solid #f0c3d6;border-radius:8px;}
QHeaderView::section{background:#fbe3ee;color:#9a4d6e;border:none;padding:4px;}
""" % {"ck": ck, "up": up, "dn": dn}


class SettingsDialog(QDialog):
    """환경설정 창 — 고른 값은 [확인]/[적용]을 눌러야 반영되고 settings.json 에 저장됨"""
    def __init__(self, app):
        super().__init__()
        self.app = app
        self.setWindowTitle(f"환경설정 — {APP_NAME}")
        self.setWindowFlags(Qt.Dialog | Qt.WindowCloseButtonHint | Qt.WindowMinimizeButtonHint)   # 항상 위 X (보고 있을 때만 펫보다 위)
        self.setMinimumWidth(640)
        self.setStyleSheet(settings_qss())
        tabs = QTabWidget()
        self.picks = {}
        self.group_btns = []
        self.group_scr = []
        self.outfit_box = {}
        # 탭 5개: 캐릭터 · 화면·움직임 · 알림·노래 · Claude · 업데이트 (예전 8개 탭을 묶음)
        etc_w = self.tab_etc()                 # Claude 탭 (여기서 만든 자동 실행·자리 비움 마중은 '화면·움직임'으로)
        parts = []
        if app.one_each and len(app.roster) >= 2:
            parts.append(("부를 친구", self.tab_chars()))
        if app.outfits:
            parts.append(("의상", self.tab_outfit()))
        if parts:
            tabs.addTab(self._stack(parts), "캐릭터")
        tabs.addTab(self._stack([("화면", self.tab_screen()), ("움직임", self.tab_play()),
                                 ("그 밖에", self.tab_more())]), "화면·움직임")
        tabs.addTab(self._stack([("알림 시각", self.tab_alarm()), ("노래 목록", self.tab_music())]), "알림·노래")
        self.tabs = tabs
        tabs.addTab(etc_w, "Claude")
        tabs.addTab(self._stack([("", self.tab_update()),
                                 ("", QLabel("설정은 프로그램 폴더의 settings.json 에 저장돼요."))]), "업데이트")
        # 탭 내용이 길어도 창이 모니터 밖으로 넘치지 않게 — 탭마다 스크롤 영역으로 감싸기
        from PyQt5.QtWidgets import QScrollArea, QFrame
        _nat = tabs.sizeHint()
        for _i in range(tabs.count()):
            _w = tabs.widget(_i)
            if isinstance(_w, QScrollArea):
                continue
            _t = tabs.tabText(_i)
            tabs.removeTab(_i)
            _sa = QScrollArea(); _sa.setWidgetResizable(True); _sa.setFrameShape(QFrame.NoFrame)
            _sa.setWidget(_w)
            tabs.insertTab(_i, _sa, _t)
        tabs.setCurrentIndex(0)
        ok, cancel, apply_ = QPushButton("확인"), QPushButton("취소"), QPushButton("적용")
        ok.setDefault(True)
        ok.clicked.connect(lambda: (self.apply(), self.close()))
        cancel.clicked.connect(self.close)
        apply_.clicked.connect(self.apply)
        bot = QHBoxLayout(); bot.addStretch(1)
        for bt in (ok, cancel, apply_):
            bot.addWidget(bt)
        lay = QVBoxLayout(self)
        _bn = os.path.join(BASE, "settings_banner.png")      # 위쪽 분홍 배너 (그림 파일이 있을 때만)
        if os.path.exists(_bn):
            self.banner = QLabel(); self.banner.setMinimumHeight(10)
            self.banner_pix = QPixmap(_bn)
            self.banner.setAlignment(Qt.AlignCenter)
            self.banner.setStyleSheet("border-radius:10px;")
            lay.addWidget(self.banner)
        lay.addWidget(tabs); lay.addLayout(bot)
        self.adjustSize()
        cur = target_screen().availableGeometry()
        # 모니터 해상도·배율에 맞춰 창 크기를 화면 안으로 제한 (넘치는 부분은 스크롤)
        _w = min(max(self.width(), _nat.width() + 40), cur.width() - 40)
        _h = min(max(self.height(), _nat.height() + 90), cur.height() - 70)
        self.resize(_w, _h)
        self.move(max(cur.left() + 10, cur.center().x() - _w // 2), max(cur.top() + 30, cur.center().y() - _h // 2))

    # 캐릭터: 등장시킬 멤버 고르기 (그룹별 체크)
    def tab_chars(self):
        """캐릭터 고르기 — 위 검색칸(초성 가능) + 왼쪽 작품 목록(고른 수) + 오른쪽 작품별·그룹별 체크"""
        from PyQt5.QtWidgets import QScrollArea, QLineEdit, QListWidget
        w = QWidget(); lay = QVBoxLayout(w)
        szbox = QGroupBox("크기"); sf = QFormLayout(szbox)
        self.size_form(sf)
        lay.addWidget(szbox)

        top = QHBoxLayout()
        self.pick_search = QLineEdit()
        self.pick_search.setPlaceholderText("🔍 이름·작품·그룹으로 찾기  (초성도 돼요: ㅎㄹㄹㅇㅂ)")
        self.pick_search.setClearButtonEnabled(True)
        self.pick_search.setStyleSheet("QLineEdit{padding:6px 8px;border:1px solid #f0bcd6;border-radius:8px;background:#fff;}")
        self.pick_search.textChanged.connect(lambda _=None: self.pick_filter())
        top.addWidget(self.pick_search, 1)
        self.pick_only = QCheckBox("고른 친구만")
        self.pick_only.toggled.connect(lambda _=False: self.pick_filter())
        top.addWidget(self.pick_only)
        for lab, fn in [("전체 선택", lambda: self.pick_set(self.app.roster)), ("전체 해제", lambda: self.pick_set([]))]:
            bt = QPushButton(lab); bt.clicked.connect(fn); top.addWidget(bt)
        lay.addLayout(top)
        self.pick_count = QLabel("")
        self.pick_count.setStyleSheet("color:#8a5a75;padding:2px 2px 4px 2px;")
        lay.addWidget(self.pick_count)

        fr = []
        used = set()
        for fname, sqs in FRANCHISE:
            sqs = [sq for sq in sqs if any(c in self.app.roster for c in SQUADS.get(sq, []))]
            if sqs:
                fr.append((fname, sqs)); used.update(sqs)
        rest_sq = [sq for sq in SQUADS if sq not in used and any(c in self.app.roster for c in SQUADS[sq])]
        if rest_sq:
            fr.append(("그 밖의 작품", rest_sq))
        loose = [c for c in self.app.roster if not any(c in SQUADS[sq] for _, sqs in fr for sq in sqs)]
        if loose:
            fr.append(("그 밖의 친구들", [None]))

        body = QHBoxLayout()
        self.fr_list = QListWidget()
        self.fr_list.setFixedWidth(200)
        self.fr_list.setStyleSheet(
            "QListWidget{background:#fff;border:1px solid #f0c8dc;border-radius:8px;outline:0;}"
            "QListWidget::item{padding:7px 8px;border-radius:6px;}"
            "QListWidget::item:selected{background:#ffd6ea;color:#7a2350;}"
            "QListWidget::item:hover{background:#fff0f7;}")
        body.addWidget(self.fr_list)
        page = QWidget(); pl = QVBoxLayout(page)
        self.fr_sections = []                      # [이름, 제목, [(상자, 격자, 멤버, 체크들, 모니터칸)], 목록 항목]
        for fname, sqs in fr:
            head = QLabel(fname)
            head.setStyleSheet("font-size:15px;font-weight:bold;color:#c8467e;padding:10px 2px 2px 2px;")
            pl.addWidget(head)
            boxes = []
            for sq in sqs:
                mem = loose if sq is None else [c for c in SQUADS[sq] if c in self.app.roster]
                if not mem:
                    continue
                box = QGroupBox(SQUAD_NAME.get(sq, "그 밖의 친구들"))
                g = QGridLayout(box)
                only = QPushButton("모두 선택")                 # 누를 때마다 이 그룹 모두 선택 ↔ 모두 해제
                only.setMaximumWidth(120)
                only.clicked.connect(lambda _=False, mem=mem: self.group_toggle(mem))
                self.group_btns.append((mem, only))
                g.addWidget(only, 0, 3)
                mc = None
                if len(QApplication.screens()) > 1:            # 모니터가 여럿이면 그룹마다 띄울 모니터
                    mc = QComboBox()
                    mc.addItem("모니터: 기본(화면 탭 설정)", "")
                    for i, sc in enumerate(QApplication.screens()):
                        gg = sc.geometry()
                        mc.addItem(f"모니터 {i + 1}" + (" (주)" if sc is QApplication.primaryScreen() else "")
                                   + f" {gg.width()}x{gg.height()}", sc.name())
                    mc.setCurrentIndex(max(0, mc.findData(CHAR_SCREEN.get(mem[0], ""))))
                    self.group_scr.append((mem, mc))
                    g.addWidget(mc, 1000, 0, 1, 4)
                cbs = []
                for n, c in enumerate(mem):
                    lab = self.app.chars[c]["label"]
                    if c in self.app.outfits and len(self.app.outfits[c]) > 1:
                        lab += f" ({len(self.app.outfits[c])}가지 모습)"
                    cb = QCheckBox(lab); cb.setChecked(c in self.app.team)
                    cb.toggled.connect(lambda _=False: self.group_labels())
                    cb._key = " ".join([lab, c, SQUAD_NAME.get(sq, "") if sq else "", fname]).lower()
                    self.picks[c] = cb
                    g.addWidget(cb, n // 3, n % 3)
                    cbs.append((c, cb))
                pl.addWidget(box)
                boxes.append((box, g, mem, cbs, mc))
            self.fr_list.addItem(fname)
            self.fr_sections.append([fname, head, boxes, self.fr_list.item(self.fr_list.count() - 1)])
        self.pick_none = QLabel("찾는 친구가 없어요. 이름 일부나 초성으로도 찾아 보세요.")
        self.pick_none.setStyleSheet("color:#a07890;padding:20px;")
        self.pick_none.hide()
        pl.addWidget(self.pick_none)
        pl.addStretch(1)
        self.pick_scroll = QScrollArea(); self.pick_scroll.setWidgetResizable(True); self.pick_scroll.setWidget(page)
        self.pick_scroll.setMinimumHeight(340)
        body.addWidget(self.pick_scroll, 1)
        lay.addLayout(body, 1)
        self.fr_list.itemClicked.connect(lambda it: self.pick_jump(it))
        # 왼쪽에서 고른 작품만 오른쪽에 보이기 (검색하거나 '고른 친구만'을 켜면 모든 작품에서 찾기)
        self.pick_fr = self.fr_sections[0][0] if self.fr_sections else None
        if self.fr_sections:
            self.fr_list.setCurrentItem(self.fr_sections[0][3])
        self.pick_filter()
        self.pick_note = QLabel("처음 켤 때는 엘리시아만 나와요. 여기서 고르면 다음에 켤 때도 그대로예요.")
        self.pick_note.setWordWrap(True)
        lay.addWidget(self.pick_note)
        return w

    @staticmethod
    def _cho(s):
        """한글 → 초성 (검색에서 'ㅎㄹ' 로 '홀로라이브' 찾기)"""
        t = "ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"
        return "".join(t[(ord(ch) - 0xAC00) // 588] if "가" <= ch <= "힣" else ch for ch in s)

    def pick_filter(self):
        """검색어·'고른 친구만' 에 맞는 캐릭터만 보이게 — 격자를 다시 채워서 빈칸 없이"""
        q = self.pick_search.text().strip().lower().replace(" ", "")
        only = self.pick_only.isChecked()
        any_vis = False
        for sec in self.fr_sections:
            fname, head, boxes, item = sec
            fr_ok = bool(q or only) or getattr(self, "pick_fr", None) in (None, fname)
            sec_vis = False
            sec_any = False
            for box, g, mem, cbs, mc in boxes:
                for c, cb in cbs:
                    g.removeWidget(cb)
                n = 0
                for c, cb in cbs:
                    k = cb._key.replace(" ", "")
                    ok = (not q or q in k or q in self._cho(k)) and (not only or cb.isChecked())
                    sec_any = sec_any or ok
                    ok = ok and fr_ok
                    cb.setVisible(ok)
                    if ok:
                        g.addWidget(cb, n // 3, n % 3); n += 1
                box.setVisible(n > 0)
                sec_vis = sec_vis or n > 0
            head.setVisible(sec_vis)
            item.setHidden(not sec_any)
            any_vis = any_vis or sec_vis
        self.pick_none.setVisible(not any_vis)
        self.pick_scroll.verticalScrollBar().setValue(0)
        self.group_labels()

    def pick_jump(self, item):
        """왼쪽 작품 이름 누르면 오른쪽엔 그 작품만 보이게 (검색어·'고른 친구만'은 풀고)"""
        for fname, head, boxes, it in self.fr_sections:
            if it is item:
                self.pick_fr = fname
                for wdg, fn in ((self.pick_search, lambda: self.pick_search.clear()),
                                (self.pick_only, lambda: self.pick_only.setChecked(False))):
                    wdg.blockSignals(True); fn(); wdg.blockSignals(False)
                self.pick_filter()
                return

    def pick_follow(self, v):
        """스크롤하면 왼쪽 목록에서 지금 보고 있는 작품을 표시"""
        cur = None
        for fname, head, boxes, it in self.fr_sections:
            if head.isVisible() and head.y() <= v + 40:
                cur = it
        if cur is None:
            return
        self.fr_list.blockSignals(True)
        self.fr_list.setCurrentItem(cur)
        self.fr_list.blockSignals(False)

    # 의상: 캐릭터별 옷 고르기 + 알아서 갈아입기
    def tab_outfit(self):
        w = QWidget(); f = QFormLayout(w)
        # 캐릭터별 옷 고르기는 우클릭 메뉴 '옷 갈아입기'로 (여기엔 켜고 끄는 것만)
        on = QLabel("옷은 캐릭터를 우클릭 → '옷 갈아입기'에서 골라요."); on.setWordWrap(True); on.setStyleSheet("color:#9a8592;")
        f.addRow("", on)
        self.oauto = QCheckBox("가끔(12~25분마다) 알아서 옷 갈아입기")
        self.oauto.setChecked(self.app.cfg.get("outfit_auto", True))
        f.addRow("", self.oauto)
        self.doro_mo = None
        if "dorothy" in self.app.outfits and os.path.exists(os.path.join(CHARS_DIR, DORO_MOTION_DIR, "0.png")):
            self.doro_mo = QCheckBox("도로롱 모션 버전 쓰기")
            self.doro_mo.setChecked(bool(self.app.cfg.get("doro_motion", False)))
            self.doro_mo.toggled.connect(self.doro_motion_warn)
            f.addRow("", self.doro_mo)
            dn = QLabel("동작이 훨씬 많지만 생김새가 원본과 달라요."); dn.setWordWrap(True); dn.setStyleSheet("color:#887;")
            f.addRow("", dn)
        return w

    def doro_motion_warn(self, on):
        if not on:
            return
        from PyQt5.QtWidgets import QMessageBox
        r = QMessageBox.question(self, "도로롱 모션 버전",
                                 "모션 버전 도로롱은 원래 도로롱과 모습이 많이 달라요!\n"
                                 "(머리가 훨씬 크고, 강아지처럼 네 발로 걸어 다니는 모습이에요)\n\n"
                                 "대신 걷기·매달리기·개성 동작·사격 같은 움직임이 훨씬 많아요.\n그래도 바꿀까요?",
                                 QMessageBox.Yes | QMessageBox.No, QMessageBox.No)
        if r != QMessageBox.Yes:
            self.doro_mo.blockSignals(True); self.doro_mo.setChecked(False); self.doro_mo.blockSignals(False)

    def pick_set(self, which):
        for c, cb in self.picks.items():
            cb.setChecked(c in which)

    def group_toggle(self, mem):
        """그룹 버튼: 다 켜져 있으면 그 그룹만 모두 끄고, 아니면 그 그룹만 모두 켬 (다른 그룹은 그대로)"""
        on = not all(self.picks[c].isChecked() for c in mem if c in self.picks)
        for c in mem:
            if c in self.picks:
                self.picks[c].setChecked(on)
        self.group_labels()

    def group_labels(self):
        for mem, bt in getattr(self, "group_btns", []):
            full = all(self.picks[c].isChecked() for c in mem if c in self.picks)
            bt.setText("모두 해제" if full else "모두 선택")
        # 왼쪽 작품 목록에 '고른 수/전체', 위에 전체 고른 수
        for fname, head, boxes, item in getattr(self, "fr_sections", []):
            cs = [cb for box, g, mem, cbs, mc in boxes for c, cb in cbs]
            on = sum(cb.isChecked() for cb in cs)
            item.setText(f"{fname}   {on}/{len(cs)}")
            head.setText(f"{fname}  ·  {on}/{len(cs)}")
        if hasattr(self, "pick_count"):
            on = sum(cb.isChecked() for cb in self.picks.values())
            self.pick_count.setText(f"고른 친구 {on}명  ·  전체 {len(self.picks)}명")

    # 화면: 모니터 · 크기 · 창 위 올라가기
    def tab_screen(self):
        w = QWidget(); f = QFormLayout(w)
        self.scs = list(QApplication.screens())
        self.mon = QComboBox()
        cur = target_screen()
        for i, sc in enumerate(self.scs):
            g = sc.geometry()
            self.mon.addItem(f"모니터 {i + 1}" + (" (주 모니터)" if sc is QApplication.primaryScreen() else "")
                             + f"   {g.width()}x{g.height()}")
        self.mon_start = next((i for i, sc in enumerate(self.scs) if sc is cur), 0)
        self.mon.setCurrentIndex(self.mon_start)
        self.mon.setEnabled(len(self.scs) > 1)
        f.addRow("띄울 모니터", self.mon)
        if len(self.scs) <= 1:
            f.addRow("", QLabel("(모니터가 하나라서 고를 게 없어요)"))
        if not getattr(self, "_sizes_done", False):      # 캐릭터 탭이 없으면(단독 버전) 크기는 여기
            self.size_form(f)
        # 흔들림·화면 그리기 (움직임 탭에서 옮겨 옴)
        self.sh = QComboBox()
        for lab, kv in SHAKE_LEVELS:
            self.sh.addItem(lab, kv)
        self.sh.setCurrentIndex(min(range(len(SHAKE_LEVELS)), key=lambda i: abs(SHAKE_LEVELS[i][1] - SHAKE["k"])))
        f.addRow("합동 장면 흔들림", self.sh)
        self.fps = QComboBox()
        for lab, v in [("부드럽게 (초당 60번, 기본)", 1), ("보통 (초당 30번, 컴퓨터가 버거울 때)", 2), ("가볍게 (초당 20번, 많이 버거울 때)", 3)]:
            self.fps.addItem(lab, v)
        self.fps.setCurrentIndex(max(0, self.fps.findData(self.app.substeps)))
        f.addRow("화면 그리기", self.fps)
        self.climb = QCheckBox("창 위에 올라가서 놀기"); self.climb.setChecked(self.app.climb_windows)
        f.addRow("", self.climb)
        self.ontop = QCheckBox("항상 위에 두기")
        self.ontop.setChecked(self.app.on_top)
        f.addRow("", self.ontop)
        note = QLabel("다른 창·전체화면 위에도 보여요. 끄면 창 뒤로 숨어요.")
        note.setWordWrap(True); note.setStyleSheet("color:#887;")
        f.addRow("", note)
        return w

    def size_form(self, f):
        """캐릭터 크기 · 말풍선 글자 크기 (합본은 캐릭터 탭 맨 위, 단독은 화면 탭)"""
        self._sizes_done = True
        # 크기: 미리 정한 크기 + 슬라이더로 세밀하게
        self.sz = QComboBox()
        for lab, v in SIZES:
            self.sz.addItem(f"{lab} ({v})", v)
        self.sz.addItem("직접 지정", 0)
        self.sl = QSlider(Qt.Horizontal); self.sl.setRange(48, 800); self.sl.setSingleStep(4); self.sl.setPageStep(20)
        self.sl_lab = QLabel()
        self.sl_lab.setMinimumWidth(48)
        self.sz.activated.connect(lambda i: self.sz.itemData(i) and self.sl.setValue(self.sz.itemData(i)))
        self.sl.valueChanged.connect(self.size_moved)
        self.sl.setValue(self.app.size); self.size_moved(self.app.size)
        row = QHBoxLayout(); row.addWidget(self.sl, 1); row.addWidget(self.sl_lab)
        f.addRow("캐릭터 크기", self.sz)
        f.addRow("", row)
        self.varied = QCheckBox("아이마다 크기 살짝 다르게"); self.varied.setChecked(bool(self.app.cfg.get("varied", False)))
        f.addRow("", self.varied)
        # 캐릭터별 크기: 고른 캐릭터만 기본 크기의 50~200%로
        from PyQt5.QtWidgets import QSpinBox
        self.cs_vals = {k: int(v) for k, v in dict(self.app.cfg.get("char_scale") or {}).items()}
        self.cs_pick = QComboBox()
        for _nm in sorted([n for n in self.app.chars if "@" not in n], key=lambda n: self.app.chars[n].get("label", n)):
            self.cs_pick.addItem(self.app.chars[_nm].get("label", _nm), _nm)
        self.cs_spin = QSpinBox(); self.cs_spin.setRange(50, 300); self.cs_spin.setSingleStep(5); self.cs_spin.setSuffix(" %")

        def _cs_load(_i=None):
            self.cs_spin.blockSignals(True)
            self.cs_spin.setValue(int(self.cs_vals.get(self.cs_pick.currentData(), 100)))
            self.cs_spin.blockSignals(False)

        def _cs_set(v):
            k = self.cs_pick.currentData()
            if k is None:
                return
            if int(v) == 100:
                self.cs_vals.pop(k, None)
            else:
                self.cs_vals[k] = int(v)
        self.cs_pick.currentIndexChanged.connect(_cs_load)
        self.cs_spin.valueChanged.connect(_cs_set)
        _cs_load()
        _cs_reset = QPushButton("모두 100%")
        _cs_reset.clicked.connect(lambda: (self.cs_vals.clear(), _cs_load()))
        _row2 = QHBoxLayout(); _row2.addWidget(self.cs_pick, 1); _row2.addWidget(self.cs_spin); _row2.addWidget(_cs_reset)
        f.addRow("캐릭터별 크기", _row2)
        self.bpx = QComboBox()
        for lab, v in BUBBLE_SIZES:
            self.bpx.addItem(f"{lab} ({v}px)", v)
        i = self.bpx.findData(BUBBLE_PX["px"])
        if i < 0:
            self.bpx.addItem(f"직접 지정 ({BUBBLE_PX['px']}px)", BUBBLE_PX["px"]); i = self.bpx.count() - 1
        self.bpx.setCurrentIndex(i)
        f.addRow("말풍선 글자 크기", self.bpx)

    def size_moved(self, v):
        self.sl_lab.setText(f"{v}px")
        i = self.sz.findData(v)
        self.sz.setCurrentIndex(i if i >= 0 else self.sz.count() - 1)

    # 움직임: 흔들림 · 자동 단체 놀이 · 말풍선
    def _stack(self, parts):
        """여러 탭 내용을 제목 상자로 묶어 한 탭에 위아래로"""
        w = QWidget(); v = QVBoxLayout(w)
        for title, wid in parts:
            if wid is None:
                continue
            if title:
                g = QGroupBox(title); gl = QVBoxLayout(g); gl.setContentsMargins(8, 6, 8, 6)
                gl.addWidget(wid); v.addWidget(g)
            else:
                v.addWidget(wid)
        v.addStretch(1)
        return w

    def resizeEvent(self, e):
        super().resizeEvent(e)
        bn = getattr(self, "banner", None)
        if bn is None or self.banner_pix.isNull():
            return
        w = max(200, self.width() - 24)
        h = max(70, min(130, w // 5))
        src = self.banner_pix
        pic = src.scaledToHeight(h, Qt.SmoothTransformation)
        canvas = QPixmap(w, h)
        pa = QPainter(canvas)
        col = src.copy(int(src.width() * 0.3), 0, 1, src.height())       # 빈 하늘 한 줄을 늘려서 왼쪽을 채움
        pa.drawPixmap(0, 0, w, h, col)
        from PyQt5.QtGui import QLinearGradient, QColor
        fade = QPixmap(pic.size()); fade.fill(Qt.transparent)              # 그림 왼쪽 끝을 부드럽게 흐려서 이음매 없애기
        p2 = QPainter(fade); p2.drawPixmap(0, 0, pic)
        p2.setCompositionMode(QPainter.CompositionMode_DestinationIn)
        g = QLinearGradient(0, 0, pic.width() * 0.4, 0)
        g.setColorAt(0, QColor(0, 0, 0, 0)); g.setColorAt(1, QColor(0, 0, 0, 255))
        p2.fillRect(fade.rect(), g); p2.end()
        pa.drawPixmap(w - pic.width(), 0, fade)                           # 그림은 오른쪽에 맞춤
        pa.end()
        bn.setPixmap(canvas)
        bn.setFixedHeight(h)

